def groupAnagrams(strs: List[str]) -> List[List[str]]:
    groups = dict()
    for word in strs:
        word_sorted = ''.join(sorted(word))
        if word_sorted in groups:
            groups[word_sorted].append(word)
        else:
            groups[word_sorted] = [word]
    return list(groups.values())

