def isValid(s: str) -> bool:
    stack = []
    for i in s:
        if i in ['(', '[', '{']:
            stack.append(i)
        elif len(stack) > 0 and (
            i == ')' and stack[-1] == '(' or
            i == ']' and stack[-1] == '[' or
            i == '}' and stack[-1] == '{'
        ):
            stack.pop()
        else:
            stack.append(i)
    return len(stack) == 0

from typing import List

def canJump(nums: List[int]) -> bool:
    far = 0
    for i, n in enumerate(nums):
        if i > far:
            return False
        far = max(far, i + n)
    return True
